1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	};
5	
6	export type Step =
7	  | { op: "quote"; items: Item[] }
8	  | { op: "claim"; policy: number; incident: Incident };
9	
10	export type Item = {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	};
16	
17	export type Incident = {
18	  cause: string;
19	  damages: Damage[];
20	};
21	
22	export type Damage = {
23	  itemType: string;
24	  amount: number;
25	};
26	
27	export type Result = { premium: number } | { payout: number; remainingCap: number };
28	
29	const PROCESSING_FEE = 5;
30	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
31	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	  potion: 40,
36	  rune: 25,
37	};
38	
39	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
40	
41	const policyBaseOf = (items: Item[]): number =>
42	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
43	
44	const quoteFor = (items: Item[]): Result => {
45	  const policyBase = policyBaseOf(items);
46	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
47	  return {
48	    premium: Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE),
49	  };
50	};
51	
52	const resultFor = (step: Step): Result => {
53	  if (step.op === "quote") return quoteFor(step.items);
54	  throw new Error(`unsupported step: ${step.op}`);
55	};
56	
57	export const runScenario = (scenario: Scenario): { results: Result[] } => ({
58	  results: scenario.steps.map(resultFor),
59	});
