// The MHPCO rounds premiums up — always in its own favour.
const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const quoteFor = (items: Item[]): Result => {
  const policyBase = policyBaseOf(items);
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
  return {
    premium: roundedInMHPCOsFavour(policyBase + firstInsuranceSurcharge + PROCESSING_FEE),
  };
};
